import json

def evaluate_statements(context, statements):
    output = []
    for statement in statements:
        verdict = 0
        reason = ""
        if statement in context:
            verdict = 1
            reason = "The statement is directly mentioned in the context."
        else:
            reason = "The statement cannot be directly inferred from the context."
        output.append({
            "statement": statement,
            "reason": reason,
            "verdict": verdict
        })
    return {"statements": output}

